/**
 * Utility to patch missing duration metadata in WebM files generated by browser MediaRecorder.
 * Based on fix-webm-duration by Yuri Sitnikov (MIT License).
 */

const sections = {
  0xa45dfa3: { name: 'EBML', type: 'Container' },
  0x286: { name: 'EBMLVersion', type: 'Uint' },
  0x2f7: { name: 'EBMLReadVersion', type: 'Uint' },
  0x2f2: { name: 'EBMLMaxIDLength', type: 'Uint' },
  0x2f3: { name: 'EBMLMaxSizeLength', type: 'Uint' },
  0x282: { name: 'DocType', type: 'String' },
  0x287: { name: 'DocTypeVersion', type: 'Uint' },
  0x285: { name: 'DocTypeReadVersion', type: 'Uint' },
  0x6c: { name: 'Void', type: 'Binary' },
  0x3f: { name: 'CRC-32', type: 'Binary' },
  0xb538667: { name: 'SignatureSlot', type: 'Container' },
  0x8538067: { name: 'Segment', type: 'Container' },
  0x14d9b74: { name: 'SeekHead', type: 'Container' },
  0xdbb: { name: 'Seek', type: 'Container' },
  0x13ab: { name: 'SeekID', type: 'Binary' },
  0x13ac: { name: 'SeekPosition', type: 'Uint' },
  0x549a966: { name: 'Info', type: 'Container' },
  0xad7b1: { name: 'TimecodeScale', type: 'Uint' },
  0x489: { name: 'Duration', type: 'Float' },
  0x654ae6b: { name: 'Tracks', type: 'Container' },
};

function doInherit(newClass, baseClass) {
  newClass.prototype = Object.create(baseClass.prototype);
  newClass.prototype.constructor = newClass;
}

function WebmBase(name, type) {
  this.name = name || 'Unknown';
  this.type = type || 'Unknown';
}
WebmBase.prototype.updateBySource = function() {};
WebmBase.prototype.setSource = function(source) {
  this.source = source;
  this.updateBySource();
};
WebmBase.prototype.updateByData = function() {};
WebmBase.prototype.setData = function(data) {
  this.data = data;
  this.updateByData();
};

function WebmUint(name, type) {
  WebmBase.call(this, name, type || 'Uint');
}
doInherit(WebmUint, WebmBase);

function padHex(hex) {
  return hex.length % 2 === 1 ? '0' + hex : hex;
}
WebmUint.prototype.updateBySource = function() {
  this.data = '';
  for (let i = 0; i < this.source.length; i++) {
    const hex = this.source[i].toString(16);
    this.data += padHex(hex);
  }
};
WebmUint.prototype.updateByData = function() {
  const length = this.data.length / 2;
  this.source = new Uint8Array(length);
  for (let i = 0; i < length; i++) {
    const hex = this.data.substr(i * 2, 2);
    this.source[i] = parseInt(hex, 16);
  }
};
WebmUint.prototype.getValue = function() {
  return parseInt(this.data, 16);
};
WebmUint.prototype.setValue = function(value) {
  this.setData(padHex(value.toString(16)));
};

function WebmFloat(name, type) {
  WebmBase.call(this, name, type || 'Float');
}
doInherit(WebmFloat, WebmBase);

WebmFloat.prototype.getFloatArrayType = function() {
  return this.source && this.source.length === 4 ? Float32Array : Float64Array;
};
WebmFloat.prototype.updateBySource = function() {
  const byteArray = this.source.slice().reverse();
  const FloatArrayType = this.getFloatArrayType();
  const floatArray = new FloatArrayType(byteArray.buffer);
  this.data = floatArray[0];
};
WebmFloat.prototype.updateByData = function() {
  const FloatArrayType = this.getFloatArrayType();
  const floatArray = new FloatArrayType([this.data]);
  const byteArray = new Uint8Array(floatArray.buffer);
  this.source = byteArray.reverse();
};
WebmFloat.prototype.getValue = function() {
  return this.data;
};
WebmFloat.prototype.setValue = function(value) {
  this.setData(value);
};

function WebmContainer(name, type) {
  WebmBase.call(this, name, type || 'Container');
}
doInherit(WebmContainer, WebmBase);

WebmContainer.prototype.readByte = function() {
  return this.source[this.offset++];
};
WebmContainer.prototype.readUint = function() {
  const firstByte = this.readByte();
  const bytes = 8 - firstByte.toString(2).length;
  let value = firstByte - (1 << (7 - bytes));
  for (let i = 0; i < bytes; i++) {
    value *= 256;
    value += this.readByte();
  }
  return value;
};
WebmContainer.prototype.updateBySource = function() {
  this.data = [];
  for (this.offset = 0; this.offset < this.source.length; this.offset = end) {
    const id = this.readUint();
    const len = this.readUint();
    var end = Math.min(this.offset + len, this.source.length);
    const data = this.source.slice(this.offset, end);

    const info = sections[id] || { name: 'Unknown', type: 'Unknown' };
    let ctr = WebmBase;
    switch (info.type) {
      case 'Container':
        ctr = WebmContainer;
        break;
      case 'Uint':
        ctr = WebmUint;
        break;
      case 'Float':
        ctr = WebmFloat;
        break;
    }
    const section = new ctr(info.name, info.type);
    section.setSource(data);
    this.data.push({
      id,
      idHex: id.toString(16),
      data: section,
    });
  }
};
WebmContainer.prototype.writeUint = function(x, draft) {
  let bytes = 1;
  let flag = 0x80;
  for (; x >= flag && bytes < 8; bytes++, flag *= 0x80) {}

  if (!draft) {
    let value = flag + x;
    for (let i = bytes - 1; i >= 0; i--) {
      const c = value % 256;
      this.source[this.offset + i] = c;
      value = (value - c) / 256;
    }
  }

  this.offset += bytes;
};
WebmContainer.prototype.writeSections = function(draft) {
  this.offset = 0;
  for (let i = 0; i < this.data.length; i++) {
    const section = this.data[i];
    const content = section.data.source;
    const contentLength = content.length;
    this.writeUint(section.id, draft);
    this.writeUint(contentLength, draft);
    if (!draft) {
      this.source.set(content, this.offset);
    }
    this.offset += contentLength;
  }
  return this.offset;
};
WebmContainer.prototype.updateByData = function() {
  const length = this.writeSections('draft');
  this.source = new Uint8Array(length);
  this.writeSections();
};
WebmContainer.prototype.getSectionById = function(id) {
  for (let i = 0; i < this.data.length; i++) {
    if (this.data[i].id === id) {
      return this.data[i].data;
    }
  }
  return null;
};

function WebmFile(source) {
  WebmContainer.call(this, 'File', 'File');
  this.setSource(source);
}
doInherit(WebmFile, WebmContainer);

WebmFile.prototype.fixDuration = function(durationMs) {
  const segmentSection = this.getSectionById(0x8538067);
  if (!segmentSection) return false;

  const infoSection = segmentSection.getSectionById(0x549a966);
  if (!infoSection) return false;

  const timeScaleSection = infoSection.getSectionById(0xad7b1);
  if (!timeScaleSection) return false;

  let durationSection = infoSection.getSectionById(0x489);
  if (durationSection) {
    if (durationSection.getValue() <= 0) {
      durationSection.setValue(durationMs);
    } else {
      return false;
    }
  } else {
    durationSection = new WebmFloat('Duration', 'Float');
    durationSection.setValue(durationMs);
    infoSection.data.push({
      id: 0x489,
      data: durationSection,
    });
  }

  timeScaleSection.setValue(1000000); // 1 millisecond
  infoSection.updateByData();
  segmentSection.updateByData();
  this.updateByData();
  return true;
};
WebmFile.prototype.toBlob = function(mimeType) {
  return new Blob([this.source.buffer], { type: mimeType || 'video/webm' });
};

/**
 * Injects duration into a WebM Blob so that video seekbars and duration work properly across browsers.
 * @param {Blob} blob
 * @param {number} durationMs - Duration in milliseconds
 * @returns {Promise<Blob>}
 */
export async function fixWebmDuration(blob, durationMs) {
  if (!blob || !durationMs || durationMs <= 0) return blob;
  return new Promise((resolve) => {
    try {
      const reader = new FileReader();
      reader.onloadend = function() {
        try {
          const file = new WebmFile(new Uint8Array(reader.result));
          if (file.fixDuration(durationMs)) {
            resolve(file.toBlob(blob.type));
            return;
          }
        } catch (_) {}
        resolve(blob);
      };
      reader.onerror = function() {
        resolve(blob);
      };
      reader.readAsArrayBuffer(blob);
    } catch (_) {
      resolve(blob);
    }
  });
}
